changeSet.sql:
ALTER TABLE nexus.catalog_document_chunks NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.chunks NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_deleted_count BIGINT;
BEGIN
    DELETE FROM nexus.catalog_document_chunks c
    WHERE NOT EXISTS (
        SELECT 1 FROM nexus.chunks v
         WHERE v.tenant_id  = c.tenant_id
           AND v.collection = c.collection
           AND v.chash      = c.chash
    );
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'RDR-191 Phase 5 manifest-FK remediation (nexus-o8dil.29): deleted % dangling catalog_document_chunks row(s) with no matching nexus.chunks row', v_deleted_count;
END $$;

ALTER TABLE nexus.chunks FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_document_chunks FORCE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION nexus.purge_trash(older_than interval) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path = nexus, public AS $$ DECLARE v_tenant TEXT; v_count BIGINT; BEGIN -- GUC guard: must have a non-empty tenant scope v_tenant := current_setting('nexus.tenant', true); IF v_tenant IS NULL OR v_tenant = '' THEN RAISE EXCEPTION 'purge_trash: nexus.tenant GUC must be set to a non-empty tenant scope. ' 'Cross-tenant purge is not permitted. Set the nexus.tenant configuration ' 'parameter before calling purge_trash.'; END IF;
-- RDR-191 Phase 5 (nexus-o8dil.29, class-B site 1): fk_catalog_chunks_chunk is -- DEFERRABLE INITIALLY IMMEDIATE (catalog-029-0). Step 1 below deletes FROM -- nexus.chunks while its referencing catalog_document_chunks rows still exist -- (removed only in Step 4, later in this same transaction) -- defer the check -- to this call's COMMIT, by which point Step 4 has cascaded them away. SET CONSTRAINTS fk_catalog_chunks_chunk DEFERRED;
-- Step 1-3 (collapsed): sweep orphaned chunk rows from the unified -- nexus.chunks. Safety contract unchanged from catalog-026-1: a chunk -- is sweepable ONLY IF it has at least one manifest row AND none of its -- manifest rows PROTECT it -- a row protects when its owning document -- is LIVE, or TOMBSTONED but still inside the older_than grace window. -- Manifest-less chunks are never swept (RDR-145 deferred scope). DELETE FROM nexus.chunks c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than) );
-- Step 4: physically delete tombstoned documents older than the threshold. -- fk-001 ON DELETE CASCADE removes catalog_document_chunks, document_aspects, -- document_highlights, and aspect_extraction_queue rows for each deleted doc. -- Unchanged from catalog-026-1 / vectors-005-15. DELETE FROM nexus.catalog_documents WHERE tenant_id = v_tenant AND deleted_at IS NOT NULL AND deleted_at <= NOW() - older_than;
GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count; END; $$

rollback.sql:
CREATE OR REPLACE FUNCTION nexus.purge_trash(older_than interval) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_tenant TEXT; v_count BIGINT; BEGIN v_tenant := current_setting('nexus.tenant', true); IF v_tenant IS NULL OR v_tenant = '' THEN RAISE EXCEPTION 'purge_trash: nexus.tenant GUC must be set to a non-empty tenant scope. ' 'Cross-tenant purge is not permitted. Set the nexus.tenant configuration ' 'parameter before calling purge_trash.'; END IF;
DELETE FROM nexus.chunks c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than) );
DELETE FROM nexus.catalog_documents WHERE tenant_id = v_tenant AND deleted_at IS NOT NULL AND deleted_at <= NOW() - older_than;
GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count; END; $$
